"""`.Combine colors`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Combine colors'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Result', 'NodeSocketShader')
    t.socket('INPUT', 'Light colors', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Dark colors', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Toon shading', 'NodeSocketFloat', subtype='FACTOR', default_value=0.5, min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Alpha mask', 'NodeSocketColor', default_value=(0.5, 0.5, 0.5, 1.0))
    t.socket('INPUT', 'Alpha mask (alpha)', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Alpha mask (custom)', 'NodeSocketColor')
    t.socket('INPUT', 'Main texture (alpha)', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Force visibility', 'NodeSocketFloat', subtype='FACTOR', default_value=0.5, min_value=0.0, max_value=1.0)
    t.socket('INPUT', 'Force custom mask', 'NodeSocketFloat', subtype='FACTOR', min_value=0.0, max_value=1.0)

    t.node('NodeFrame', 'Frame.002', props={
        'location': (9.200012, -52.800003),
        'width': 572.0,
        'height': 372.40002,
        'label': 'Switch between light color, dark color, or transparent',
        'color': (0.604, 0.604, 0.604),
    })
    t.node('NodeFrame', 'Frame.007', props={
        'location': (-563.2, -445.4),
        'width': 831.2,
        'height': 236.4,
        'label': 'Parse alpha masks (Assume white or filled for all slots)',
        'color': (0.604, 0.604, 0.604),
    })
    t.node('NodeFrame', 'Frame.010', parent='Frame.007', props={
        'location': (598.80005, -40.0),
        'width': 202.4,
        'height': 166.4,
        'label': 'Add custom mask or forced visibility',
        'color': (0.604, 0.604, 0.604),
    })
    t.node('NodeFrame', 'Frame.008', parent='Frame.007', props={
        'location': (30.0, -63.200043),
        'width': 202.40002,
        'height': 132.79999,
        'label': 'Get red channel',
        'color': (0.604, 0.604, 0.604),
    })
    t.node('NodeFrame', 'Frame.009', parent='Frame.007', props={
        'location': (281.2, -41.600006),
        'width': 202.4,
        'height': 132.0,
        'label': 'Multiply the two together',
        'color': (0.604, 0.604, 0.604),
    })
    t.node('NodeGroupInput', 'Group Input.002', hide_outputs=('Light colors', 'Dark colors', 'Toon shading', 9), props={
        'location': (-777.3176, -497.17773),
    })
    t.node('ShaderNodeMixShader', 'Mix Shader', parent='Frame.002', props={
        'location': (221.46785, -39.715164),
    })
    t.node('NodeGroupOutput', 'Group Output', parent='Frame.002', hide_inputs=(1,), props={
        'location': (401.88437, -40.12059),
    })
    t.node('ShaderNodeBsdfTransparent', 'Transparent BSDF', parent='Frame.002', hide_inputs=('Color', 'Weight'), props={
        'location': (29.70282, -40.324852),
    })
    t.node('ShaderNodeSeparateColor', 'Separate Color.002', parent='Frame.008', props={
        'location': (30.077911, -44.904724),
        'hide': True,
    })
    t.node('ShaderNodeSeparateColor', 'Separate Color.003', parent='Frame.008', props={
        'location': (32.457336, -77.931946),
        'hide': True,
    })
    t.node('ShaderNodeMath', 'Math.004', parent='Frame.010', props={
        'location': (30.00879, -45.286774),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })
    t.node('ShaderNodeMix', 'Mix.004', parent='Frame.010', inputs={'Factor_Float': 0.0}, outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, props={
        'location': (30.76593, -77.91556),
        'hide': True,
    })
    t.node('ShaderNodeMath', 'Math.005', parent='Frame.010', props={
        'location': (32.056335, -111.49454),
        'hide': True,
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math.003', parent='Frame.009', props={
        'location': (32.08081, -77.38733),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })
    t.node('ShaderNodeMath', 'Math', parent='Frame.009', props={
        'location': (30.144958, -45.099915),
        'hide': True,
        'operation': 'MULTIPLY',
        'use_clamp': True,
    })
    t.node('ShaderNodeMix', 'mix', parent='Frame.002', inputs={'Factor_Float': 0.5}, hide_inputs=('Factor_Vector', 'A_Float', 'B_Float', 'A_Vector', 'B_Vector'), outputs={'Result_Color': (0.0, 0.0, 0.0, 0.0)}, hide_outputs=('Result_Float', 'Result_Vector'), props={
        'location': (29.634338, -122.529465),
        'data_type': 'RGBA',
    })
    t.node('NodeGroupInput', 'input', hide_outputs=('Alpha mask', 'Alpha mask (alpha)', 'Main texture (alpha)', 'Force visibility', 'Force custom mask', 9), props={
        'location': (-211.7889, -305.6416),
    })

    t.link('input', 'Toon shading', 'mix', 'Factor_Float')
    t.link('mix', 'Result_Color', 'Mix Shader', 'Shader_001')
    t.link('Mix Shader', 'Shader', 'Group Output', 'Result')
    t.link('Transparent BSDF', 'BSDF', 'Mix Shader', 'Shader')
    t.link('Group Input.002', 'Alpha mask (custom)', 'Separate Color.003', 'Color')
    t.link('Group Input.002', 'Alpha mask', 'Separate Color.002', 'Color')
    t.link('Separate Color.002', 'Red', 'Math', 'Value')
    t.link('Group Input.002', 'Alpha mask (alpha)', 'Math', 'Value_001')
    t.link('Math', 'Value', 'Math.003', 'Value')
    t.link('Group Input.002', 'Main texture (alpha)', 'Math.003', 'Value_001')
    t.link('Math.003', 'Value', 'Mix.004', 'A_Float')
    t.link('Math.003', 'Value', 'Math.004', 'Value')
    t.link('Separate Color.003', 'Red', 'Math.004', 'Value_001')
    t.link('Math.004', 'Value', 'Mix.004', 'B_Float')
    t.link('Group Input.002', 'Force custom mask', 'Mix.004', 'Factor_Float')
    t.link('Mix.004', 'Result_Float', 'Math.005', 'Value')
    t.link('Group Input.002', 'Force visibility', 'Math.005', 'Value_001')
    t.link('Math.005', 'Value', 'Mix Shader', 'Fac')
    t.link('input', 'Light colors', 'mix', 'B_Color')
    t.link('input', 'Dark colors', 'mix', 'A_Color')
    return t
